<?php require 'header.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$s=db()->prepare('SELECT o.*,c.id customer_id,c.full_name,c.phone,c.whatsapp,c.email,c.address FROM orders o JOIN customers c ON c.id=o.customer_id WHERE o.id=?');$s->execute([$id]);$o=$s->fetch();if(!$o){http_response_code(404);echo '<p>Order not found.</p>';require 'footer.php';exit;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['full_name']??'');$phone=trim($_POST['phone']??'');$wa=trim($_POST['whatsapp']??'');$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$address=trim($_POST['address']??'');$eta=trim($_POST['estimated_delivery']??'');if(!$name||!$phone||!$wa||!$email||!$address||($eta!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$eta))){flash('error','Complete all details and enter a valid estimated delivery date.');}else{$pdo=db();$pdo->beginTransaction();$pdo->prepare('UPDATE customers SET full_name=?,phone=?,whatsapp=?,email=?,address=? WHERE id=?')->execute([$name,$phone,$wa,$email,$address,$o['customer_id']]);$pdo->prepare('UPDATE orders SET estimated_delivery=? WHERE id=?')->execute([$eta?:null,$id]);$pdo->prepare('INSERT INTO admin_audit_log(admin_id,action,entity_type,entity_id,detail) VALUES(?,?,?,?,?)')->execute([$_SESSION['admin_id'],'order_edit','order',$o['order_number'],'Updated customer delivery details and estimated delivery date']);$pdo->commit();flash('success','Order details updated.');header('Location: order-details.php?id='.$id);exit;}}?><div class="admin-title"><p><?=e($o['order_number'])?></p><h2>Edit order details</h2></div><section class="admin-panel"><form class="settings-form" method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label>Customer name<input name="full_name" required value="<?=e($o['full_name'])?>"></label><label>Phone<input name="phone" required value="<?=e($o['phone'])?>"></label><label>WhatsApp<input name="whatsapp" required value="<?=e($o['whatsapp'])?>"></label><label>Email<input name="email" type="email" required value="<?=e($o['email'])?>"></label><label>Delivery address<textarea name="address" required><?=e($o['address'])?></textarea></label><label>Estimated delivery<input name="estimated_delivery" type="date" value="<?=e($o['estimated_delivery']??'')?>"></label><button class="save">Save changes</button></form></section><?php require 'footer.php';
